#include <bits/stdc++.h>
using namespace std;const int N=262144,P=998244353,G=3;int a[N],b[N],x[N],y[N],r[N];int q(int a,int b=P-2){int s=1;for(;b;b>>=1,a=1LL*a*a%P)if(b&1)s=1LL*s*a%P;return s;}void f(int*a,int n,int z){for(int i=0;i<n;i++)if(i<r[i])swap(a[i],a[r[i]]);for(int l=2;l<=n;l<<=1){int w=q(G,(P-1)/l);if(z<0)w=q(w);for(int i=0;i<n;i+=l)for(int j=0,t=1;j<l/2;j++,t=1LL*t*w%P){int u=a[i+j],v=1LL*t*a[i+j+l/2]%P;a[i+j]=(u+v)%P;a[i+j+l/2]=(u-v+P)%P;}}if(z<0){int w=q(n);for(int i=0;i<n;i++)a[i]=1LL*a[i]*w%P;}}void s(int l,int h){if(l==h)return;int m=(l+h)>>1;s(l,m);int n=1,k=0;while(n<(m-l+1)+(h-l+1)-1)n<<=1;while((1<<k)<n)k++;for(int i=0;i<n;i++)x[i]=i<=m-l?a[l+i]:0,y[i]=i&&i<=h-l?b[i]:0,r[i]=(r[i>>1]>>1)|((i&1)<<(k-1));f(x,n,1);f(y,n,1);for(int i=0;i<n;i++)x[i]=1LL*x[i]*y[i]%P;f(x,n,-1);for(int i=m+1;i<=h;i++)a[i]=(a[i]+x[i-l])%P;s(m+1,h);}int main(){ios::sync_with_stdio(0);cin.tie(0);int n;cin>>n;for(int i=1;i<n;i++)cin>>b[i];a[0]=1;s(0,n-1);for(int i=0;i<n;i++)cout<<a[i]<<' ';cout<<'\n';}
